MODULE GPNORM_TRANSTL_ARGS_INFO_MOD

USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT

IMPLICIT NONE

PRIVATE
PUBLIC :: ARGS_INFO

! Shapes of the array arguments to GPNORM_TRANSTL
TYPE, BIND(C) :: ARGS_INFO
  INTEGER(KIND=C_INT) :: IGP_SHAPE(3)
  INTEGER(KIND=C_INT) :: IPAVE_SHAPE(1)
END TYPE ARGS_INFO

END MODULE GPNORM_TRANSTL_ARGS_INFO_MOD

SUBROUTINE GPNORM_TRANSTL(PGP, KFIELDS, KPROMA, PAVE, KRESOL)

USE PARKIND1,                     ONLY: JPRB, JPIM
USE, INTRINSIC :: ISO_C_BINDING,  ONLY: C_INT, C_PTR, C_LOC, C_NULL_PTR
USE GPNORM_TRANSTL_ARGS_INFO_MOD, ONLY: ARGS_INFO

IMPLICIT NONE

INTERFACE
SUBROUTINE GPNORM_TRANSTL_CPP_BINDING_SP(ARGS, KFIELDS, KPROMA, KRESOL, PGP, PAVE) &
  &  BIND(C, NAME="gpnorm_transtl_sp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_FLOAT, C_INT, C_PTR
  USE GPNORM_TRANSTL_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KFIELDS
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KPROMA
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KRESOL
  REAL(KIND=C_FLOAT),            INTENT(IN)  :: PGP(*)
  REAL(KIND=C_FLOAT),            INTENT(OUT) :: PAVE(*)
END SUBROUTINE GPNORM_TRANSTL_CPP_BINDING_SP
SUBROUTINE GPNORM_TRANSTL_CPP_BINDING_DP(ARGS, KFIELDS, KPROMA, KRESOL, PGP, PAVE) &
  &  BIND(C, NAME="gpnorm_transtl_dp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_DOUBLE, C_INT, C_PTR
  USE GPNORM_TRANSTL_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KFIELDS
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KPROMA
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KRESOL
  REAL(KIND=C_DOUBLE),           INTENT(IN)  :: PGP(*)
  REAL(KIND=C_DOUBLE),           INTENT(OUT) :: PAVE(*)
END SUBROUTINE GPNORM_TRANSTL_CPP_BINDING_DP
END INTERFACE

REAL(KIND=JPRB),              INTENT(IN)  :: PGP(:,:,:)
REAL(KIND=JPRB),              INTENT(OUT) :: PAVE(:)
INTEGER(KIND=JPIM),           INTENT(IN)  :: KFIELDS
INTEGER(KIND=JPIM),           INTENT(IN)  :: KPROMA
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KRESOL

TYPE(ARGS_INFO) :: ARGS

TYPE(C_PTR) :: KRESOL_PTR
INTEGER(KIND=C_INT), TARGET :: IRESOL

ARGS%IGP_SHAPE = SHAPE(PGP, KIND=C_INT)
ARGS%IPAVE_SHAPE = SHAPE(PAVE, KIND=C_INT)

IF (PRESENT(KRESOL)) THEN
  IRESOL = KRESOL
  KRESOL_PTR = C_LOC(IRESOL)
ELSE
  KRESOL_PTR = C_NULL_PTR
ENDIF

#ifdef TRANS_SINGLE
CALL GPNORM_TRANSTL_CPP_BINDING_SP(ARGS, KFIELDS, KPROMA, KRESOL_PTR, PGP, PAVE)
#else
CALL GPNORM_TRANSTL_CPP_BINDING_DP(ARGS, KFIELDS, KPROMA, KRESOL_PTR, PGP, PAVE)
#endif

END SUBROUTINE GPNORM_TRANSTL
